// Test support for the OTDR library.
//
// The real measurement sets are customer data: they are NEVER copied into the repository. Tests that need them read
// their location from environment variables and are skipped when they are not set:
//   OTDR_SAMPLES_DIR    folder holding the .sor sample sets (one sub-folder per set)
//   OTDR_EXAMPLES_DIR   golden files generated by the previous tool from the distribution sample set
//   OTDR_REFERENCE_DIR  original reference files of the operator tools (FiberCable exports, GDCO macro DCO):
//                         transport-loop/SOR/*.sor + transport-loop/*.txt (FiberCable export) + transport-loop/*.xlsx
//                         (FiberCable measurement dossier, saved as .xlsx when FiberCable gave an .xls);
//                         delivered/TRANSPORT/SOR/{FTTH,FTTE} and delivered/DISTRIBUTION/SOR (.sor + FiberCable .txt
//                         [+ FiberCable measurement dossier .xlsx] [+ Base ROP .csv]), the reference DCO in
//                         delivered/TRANSPORT ({FTTH,FTTE}_*.xlsx) and delivered/DISTRIBUTION; failed-repairs/ (operator
//                         failed-repair report .xlsx + the .sor measured before the repairs).
// Sample sets, cables and files are selected by a SHA-256 prefix of their name, so that no customer identifier is
// written in the tests.
import { createHash } from 'node:crypto';
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { type InputFile, parseSorName } from '../../../resources/js/otdr';
import { TXT } from '../../../resources/js/otdr/export/format';

const env = (name: string): string | null => {
    const v = process.env[name];

    return v && existsSync(v) ? v : null;
};

export const SAMPLES_DIR = env('OTDR_SAMPLES_DIR');
export const EXAMPLES_DIR = env('OTDR_EXAMPLES_DIR');
export const REFERENCE_DIR = env('OTDR_REFERENCE_DIR');

const sha = (s: string) => createHash('sha256').update(s).digest('hex');

/** Sample set folder whose name hash starts with `prefix`, or null. */
function sampleSet(prefix: string): string | null {
    if (!SAMPLES_DIR) {
        return null;
    }

    const name = readdirSync(SAMPLES_DIR).find((n) => sha(n).startsWith(prefix));

    return name ? join(SAMPLES_DIR, name) : null;
}

/** Sample sets: looped transport (24 traces), complete distribution of a PM (932 traces), SmartOTDR 25.6.6 without markers, SmartOTDR + MTS 4000. */
export const SETS = {
    transportLoop: sampleSet('57add99583d8'),
    distribution: sampleSet('bcae0416621b'),
    smartOtdr: sampleSet('540c327e1a96'),
    mixedOtdr: sampleSet('6f8f337248c7'),
};

/** Reference originals (OTDR_REFERENCE_DIR). */
export const REFERENCE = REFERENCE_DIR
    ? {
        transportLoop: join(REFERENCE_DIR, 'transport-loop'),
        ftth: join(REFERENCE_DIR, 'delivered/TRANSPORT/SOR/FTTH'),
        ftte: join(REFERENCE_DIR, 'delivered/TRANSPORT/SOR/FTTE'),
        distribution: join(REFERENCE_DIR, 'delivered/DISTRIBUTION/SOR'),
        delivered: join(REFERENCE_DIR, 'delivered'),
        failedRepairs: join(REFERENCE_DIR, 'failed-repairs'),
    }
    : null;

export const hasSamples = SETS.transportLoop !== null && SETS.distribution !== null;
export const hasReference = REFERENCE !== null && existsSync(REFERENCE.transportLoop) && existsSync(REFERENCE.distribution);

export function loadSorFolder(dir: string | null): InputFile[] {
    if (!dir) {
        return [];
    }

    return readdirSync(dir)
        .filter((n) => /\.sor$/i.test(n))
        .map((n) => ({ name: n, bytes: new Uint8Array(readFileSync(join(dir, n))) }));
}

/** First file of a folder matching a pattern. */
export const fileIn = (dir: string, re: RegExp): string => join(dir, readdirSync(dir).find((n) => re.test(n)) ?? '');

/** Files whose name hash starts with `prefix`. */
export const byNameHash = (files: InputFile[], prefix: string) => files.filter((f) => sha(f.name).startsWith(prefix));

/** Files of the cable whose id hash starts with `prefix`. */
export const byCableHash = (files: InputFile[], prefix: string) => files.filter((f) => sha(parseSorName(f.name)?.cableId ?? '').startsWith(prefix));

/** The reference deliverables were produced with the events recorded by the OTDR only. */
export const OTDR_ONLY = { completeAnalysis: false } as const;

// ------------------------------------------------------------------ FiberCable 2 export reader (parity reference)

export type Row = (number | null)[];

export interface FcExport {
    atten: Map<string, Row>;
    slope: Map<string, Row>;
    length: Map<string, Row>;
    refl: Map<string, Row>;
}

const SECTIONS: Record<string, keyof FcExport> = {
    [TXT.sections.attenuations]: 'atten',
    [TXT.sections.slopes]: 'slope',
    [TXT.sections.lengths]: 'length',
    [TXT.sections.reflectances]: 'refl',
};

const num = (v: string): number | null => {
    const t = v.trim();

    if (!t) {
        return null;
    }

    const n = Number(t.replace(',', '.'));

    return Number.isFinite(n) ? n : null;
};

export const rowKey = (cable: string, fiber: number, lambda: number) => `${cable}|${fiber}|${lambda}`;

export const readUtf16 = (path: string) => new TextDecoder('utf-16le').decode(readFileSync(path)).replace(/^﻿/, '');

export function readFcExport(path: string): FcExport {
    const text = readUtf16(path);
    const out: FcExport = { atten: new Map(), slope: new Map(), length: new Map(), refl: new Map() };
    let cur: keyof FcExport | null = null;
    const done = new Set<string>();

    for (const line of text.split(/\r?\n/)) {
        const title = line.trim();

        if (title in SECTIONS) {
            cur = SECTIONS[title]!;
            continue;
        }

        if (title.startsWith(TXT.sections.constraints) || title.startsWith(TXT.sections.information)) {
            cur = null;
            continue;
        }

        const p = line.split('\t');

        if (!cur || p.length < 4 || !/^\d+$/.test(p[1]!.trim())) {
            continue;
        }

        const k = rowKey(p[0]!.trim(), Number(p[1]), Number(p[2]));

        // table repeated at the end of the export
        if (out[cur].has(k)) {
            done.add(cur);
            continue;
        }

        if (!done.has(cur)) {
            out[cur].set(k, p.slice(3).map(num));
        }
    }

    return out;
}
